#!/bin/bash
# devshop-commit-guard.sh — commit-time guard for devshop hygiene.
# Called from .hooks/pre-commit (generated by init-devshop.sh, invoked by husky).
# git -c bypass flags work natively in husky context (inherited by child processes).
#
# Three checks (all blocking via exit 1). Each check has a name; the runner
# executes them in the order listed below:
#
#   mixed-commit       (DETERMINISTIC, project repo only)
#                      devshop + project files staged together → block
#   docs-reviewed      (SEMANTIC)
#                      tooling changed → reviews ALL docs (including ones that
#                      don't yet mention the change — new features need
#                      first-time docs) AND, when reference docs are staged,
#                      attests cross-file coherence in the same review.
#                      (Merged 2026-04-27 from the former docs-drift +
#                      doc-consistency pair — they had near-identical
#                      rejection criteria and the dual call was redundant.)
#   release-coverage   (SEMANTIC, devshop repo only)
#                      kit/version staged → adversarial review of whether changes
#                      since last tag have adequate test coverage
#
# (The cross-repo blocking check was removed in v1.20.0 — its lockstep
# assumption only held during single-project dogfooding; in a multi-project
# world it became near-pure friction. The session-start.sh "cross-repo WIP
# heads-up" advisory remains and is the better fit for the current shape.)
#
# Semantic checks always run an adversarial review (adversarial-review.sh) —
# either of a review reason provided via git -c flag, or (for release-coverage)
# of the actual coverage directly. Deterministic checks auto-pass when the
# condition is met.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"

# --- Repo detection ---
GIT_ROOT=$(git rev-parse --show-toplevel 2>/dev/null || echo "")
# Detect devshop-self mode: workspace IS the devshop repo (opened directly in VS Code).
# kit/ is a real directory in the devshop repo but .devshopkit/ is always a symlink in projects.
if [ "$GIT_ROOT" != "/devshop" ] && [ -d "$GIT_ROOT/kit" ] && [ ! -L "$GIT_ROOT/kit" ]; then
  # Devshop-self mode: devshop opened directly as workspace
  CURRENT_REPO=devshop
else
  case "$GIT_ROOT" in
    /workspace) CURRENT_REPO=project ;;
    /devshop)   CURRENT_REPO=devshop ;;
    *)          CURRENT_REPO=unknown ;;
  esac
fi

STAGED=$(git diff --cached --name-only)
[ -z "$STAGED" ] && exit 0

FAILED=false

# --- Classify staged files ---
DEVSHOP_PATTERNS=(
  '^\.devshopkit/'
  '^\.claude/'
  '^\.dcg\.toml$'
)
DEVSHOP_REGEX=$(IFS='|'; echo "${DEVSHOP_PATTERNS[*]}")

DEVSHOP_FILES=()
PROJECT_FILES=()

while IFS= read -r file; do
  [ -z "$file" ] && continue
  if echo "$file" | grep -qE "$DEVSHOP_REGEX"; then
    DEVSHOP_FILES+=("$file")
  else
    PROJECT_FILES+=("$file")
  fi
done <<< "$STAGED"

# --- mixed-commit (DETERMINISTIC, project repo only) ---
if [ "$CURRENT_REPO" = "project" ]; then
  if [ ${#DEVSHOP_FILES[@]} -gt 0 ] && [ ${#PROJECT_FILES[@]} -gt 0 ]; then
    echo ""
    echo "✖ Mixed commit: devshop + project files staged together."
    echo "  Devshop changes should be in separate commits."
    echo ""
    echo "  Devshop files:"
    for f in "${DEVSHOP_FILES[@]}"; do echo "    $f"; done
    echo "  Project files:"
    for f in "${PROJECT_FILES[@]}"; do echo "    $f"; done
    echo ""
    echo "  Unstage one set and commit separately."
    FAILED=true
  fi

fi

# --- docs-reviewed (SEMANTIC) — merged docs-drift + doc-consistency ---
# When devshop tooling changes, ALWAYS require a review explanation. Single
# adversarial review judges (a) per-doc enumeration of the 7 reference docs,
# (b) cross-file coherence when reference docs are staged in the same commit,
# (c) new-capability docs at the right level. Merged 2026-04-27 from the
# former docs-drift + doc-consistency pair (near-identical rejection criteria
# made the dual call redundant). One bypass flag now: devshop.docsReviewed.
RUN_DOCS_CHECK=false
if [ "$CURRENT_REPO" = "devshop" ]; then
  RUN_DOCS_CHECK=true
elif [ "$CURRENT_REPO" = "project" ] && [ ${#DEVSHOP_FILES[@]} -gt 0 ]; then
  RUN_DOCS_CHECK=true
fi

if [ "$RUN_DOCS_CHECK" = true ]; then
  # Skip changelog-only / version-only commits
  if [ "$CURRENT_REPO" = "devshop" ]; then
    # Devshop repo: every working-tree file IS devshop (the repo's whole
    # purpose is the devshop). Anything staged triggers the check except
    # release artifacts — CHANGELOG bumps and `kit/version` updates are
    # mechanical outputs of the release workflow, not tooling changes.
    # No include-list: when we enumerate "what counts as tooling," we
    # inevitably miss surfaces (skills under `.claude/skills/devshop/` were
    # the gap that motivated this file; `.claude/settings.json` + devcontainer
    # configs would be the next). Match-all-minus-exclusions is future-proof
    # — new subdirectories auto-trigger without a hook edit. The adversarial
    # review of `devshop.docsReviewed` judges whether the notes adequately
    # explain the change, so trivial edits can still pass with appropriate
    # justification ("lockfile bump, no docs needed" etc.).
    NON_CHANGELOG=$(echo "$STAGED" | grep -vE '^kit/(docs/CHANGELOG\.md|version)$' || true)
  else
    # In project repos, devshop files are under .devshopkit/, .claude/, or .dcg.toml
    NON_CHANGELOG=$(echo "$STAGED" | grep -E "$DEVSHOP_REGEX" | grep -vE '^\.devshopkit/(docs/CHANGELOG\.md|version)$' || true)
  fi

  if [ -n "$NON_CHANGELOG" ]; then
    # Detect whether reference docs are also staged — surfaces in the blocking
    # message so the operator knows the cross-file coherence rule kicks in.
    REFERENCE_DOCS_STAGED=""
    if [ "$CURRENT_REPO" = "devshop" ]; then
      REFERENCE_DOCS_STAGED=$(echo "$STAGED" | grep -E '^(CLAUDE\.md$|kit/docs/(OVERVIEW|FAQ)\.md$|kit/docs/guide/)' || true)
    else
      REFERENCE_DOCS_STAGED=$(echo "$STAGED" | grep -E '^\.devshopkit/docs/(OVERVIEW|FAQ)\.md$|^\.devshopkit/docs/guide/' || true)
    fi

    REVIEW_NOTES=$(git config --get devshop.docsReviewed 2>/dev/null || true)

    if [ -n "$REVIEW_NOTES" ]; then
      # Review notes provided — run adversarial review
      echo "⏳ Docs reviewed: reviewing notes with adversarial agent..."
      REVIEW_RESULT=$(bash "$SCRIPT_DIR/../adversarial-review.sh" docsReviewed "$REVIEW_NOTES" 2>&1) || {
        echo ""
        echo "✖ ADVERSARIAL REVIEW REJECTED your docs review notes."
        echo "  $REVIEW_RESULT"
        echo ""
        echo "  Address the finding above, then update your review notes and retry."
        FAILED=true
      }
      if [ "$FAILED" = false ]; then
        echo "✓ Docs reviewed: adversarial review accepted."
      fi
    else
      echo ""
      echo "✖ BLOCKING: Devshop tooling changed — docs review required."
      echo ""
      echo "  Changed devshop files:"
      echo "$NON_CHANGELOG" | sed 's/^/    /'
      if [ -n "$REFERENCE_DOCS_STAGED" ]; then
        echo ""
        echo "  Reference docs ALSO staged — cross-file coherence will be checked:"
        echo "$REFERENCE_DOCS_STAGED" | sed 's/^/    /'
      fi
      echo ""
      echo "  Review ALL of these docs — even if they don't mention the changed code yet"
      echo "  (new functionality needs to be documented for the first time):"
      echo "    kit/docs/OVERVIEW.md   — devshop overview (incl. § Concept)"
      echo "    kit/docs/guide/        — operational reference (workflow, conventions, hooks, security, architecture, ops)"
      echo "    CLAUDE.md               — devshop conventions (repo root)"
      echo "    kit/docs/FAQ.md        — design rationale"
      echo "    README.md              — user-facing description and commands"
      echo ""
      echo "  1. Read each doc above"
      echo "  2. Check if the committed changes introduce, modify, or remove"
      echo "     something that should be reflected — including new additions"
      echo "  3. Stage any doc updates"
      echo "  4. Retry with your review notes (single bypass flag for both"
      echo "     coverage and cross-file-coherence concerns):"
      echo "     git -c devshop.docsReviewed=\"<per-doc affected/not-affected enumeration; cross-file coherence attestation when reference docs are staged>\" commit ..."
      echo ""
      echo "  Your notes will be verified by an independent reviewer."
      FAILED=true
    fi
  fi
fi

# --- release-coverage (SEMANTIC, devshop repo only) ---
# Fires when kit/version is staged (a release/version-bump commit). Reviews
# whether all changes since the last release tag have adequate test coverage.
# The adversarial review is PRIMARY (not a bypass review) — it judges coverage
# directly. On FAIL, the committer can add tests + retry, or bypass via
# `git -c devshop.releaseReviewed="<why>"` which re-runs the review with the
# justification included in context.
if [ "$CURRENT_REPO" = "devshop" ] && echo "$STAGED" | grep -q '^kit/version$'; then
  OLD_VERSION=$(git show HEAD:kit/version 2>/dev/null | tr -d '[:space:]' || true)
  if [ -n "$OLD_VERSION" ]; then
    LAST_TAG="v$OLD_VERSION"
    if git rev-parse "$LAST_TAG" &>/dev/null; then
      CHANGED_FILES=$(git diff --cached --name-only "$LAST_TAG" 2>/dev/null || true)
      TEST_CHANGES=$(echo "$CHANGED_FILES" | grep '^kit/tests/' || true)
      FULL_DIFF=$(git diff --cached "$LAST_TAG" 2>/dev/null | head -500 || true)

      TEST_SUMMARY=""
      for tf in kit/tests/*.bats; do
        [ -f "$tf" ] || continue
        TEST_SUMMARY+="--- $(basename "$tf") ---
$(grep '@test ' "$tf" | sed 's/.*@test "//;s/".*//')
"
      done

      BYPASS_REASON=$(git config --get devshop.releaseReviewed 2>/dev/null || true)

      REVIEW_CONTEXT="Release commit — reviewing coverage of all changes since $LAST_TAG.

Files changed since $LAST_TAG:
$CHANGED_FILES

Test files modified since $LAST_TAG:
${TEST_CHANGES:-(none)}

Full diff since last tag (first 500 lines):
$FULL_DIFF

Test suite coverage (test names per file):
$TEST_SUMMARY"

      if [ -n "$BYPASS_REASON" ]; then
        REVIEW_CONTEXT="$REVIEW_CONTEXT

Developer's justification for why any coverage gap is acceptable:
$BYPASS_REASON"
      fi

      echo "⏳ Release coverage: reviewing with adversarial agent..."
      REVIEW_RESULT=$(bash "$SCRIPT_DIR/../adversarial-review.sh" testCoverage "$REVIEW_CONTEXT" 2>&1) || {
        echo ""
        echo "✖ Pre-release test coverage review FAILED."
        echo "  $REVIEW_RESULT"
        echo ""
        if [ -z "$BYPASS_REASON" ]; then
          echo "  Address the gap (add tests or update existing ones), or bypass with:"
          echo "    git -c devshop.releaseReviewed=\"<why current coverage is sufficient>\" commit ..."
        else
          echo "  Your justification was rejected. Address the finding above or refine the justification."
        fi
        FAILED=true
      }
      if [ "$FAILED" = false ]; then
        echo "✓ Release coverage: adversarial review accepted."
      fi
    fi
  fi
fi

if [ "$FAILED" = true ]; then
  exit 1
fi
